import{_ as i,a0 as e,w as r,s as a,ao as l,I as o,x as n,a1 as p,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"Linux有問必答： 當使用代理服務器連接互聯網時如何安裝 Ubuntu 桌面版 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答： 當使用代理服務器連接互聯網時如何安裝 Ubuntu 桌面版 | LCTT (201511) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答： 當使用代理服務器連接互聯網時如何安裝 Ubuntu 桌面版 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答： 當使用代理服務器連接互聯網時如何安裝 Ubuntu 桌面版 | LCTT (201511) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201511/20151019 Linux FAQs with Answers--How to install Ubuntu desktop behind a proxy","title":"Linux有問必答： 當使用代理服務器連接互聯網時如何安裝 Ubuntu 桌面版","tag":"201511","desc":""},"relativePath":"201511/20151019 Linux FAQs with Answers--How to install Ubuntu desktop behind a proxy.md","filePath":"[post].md"}'),b={name:"201511/20151019 Linux FAQs with Answers--How to install Ubuntu desktop behind a proxy.md"};function d(m,t,c,x,_,f){const u=e("Link");return r(),a("div",null,[t[13]||(t[13]=l(`<h1 id="linux有問必答-當使用代理服務器連接互聯網時如何安裝-ubuntu-桌面版" tabindex="-1">Linux有問必答： 當使用代理服務器連接互聯網時如何安裝 Ubuntu 桌面版 <a class="header-anchor" href="#linux有問必答-當使用代理服務器連接互聯網時如何安裝-ubuntu-桌面版" aria-label="Permalink to “Linux有問必答： 當使用代理服務器連接互聯網時如何安裝 Ubuntu 桌面版”">​</a></h1><blockquote><p><strong>提問：</strong> 我的電腦連接到的公司網絡是使用HTTP代理連上互聯網的。當我想使用CD-ROM安裝Ubuntu時，安裝在嘗試獲取文件時被停滯了，可能是由於代理的原因。然而問題是Ubuntu的安裝程序從來沒有在安裝過程中提示我配置代理。我該怎樣通過代理服務器安裝Ubuntu桌面版？</p></blockquote><p>不像Ubuntu服務器版，Ubuntu桌面版的安裝非常自動化，沒有留下太多的自定義空間，就像自定義磁盤分區，手動網絡設置，包選擇等等。雖然這種簡單的，一鍵安裝被認為是用户友好的，但卻是那些尋找“高級安裝模式”來定製自己的Ubuntu桌面安裝的用户不希望的。</p><p>除此之外，默認的Ubuntu桌面版安裝器的一個大問題是缺少代理設置。如果你電腦在代理後面，你會看到Ubuntu在準備下載文件的時候停滯了。</p><p><img src="https://c2.staticflickr.com/6/5683/22195372232_cea81a5e45_c.jpg" alt=""></p><p>這篇文章描述瞭如何解除Ubuntu安裝限制以及<strong>如何通過代理服務器安裝Ubuntu桌面</strong>。</p><p>基本的想法是這樣的。首先啓動到live Ubuntu桌面中而不是直接啓動Ubuntu安裝器，配置代理設置並且手動在live Ubuntu中啓動Ubuntu安裝器。下面是步驟。</p><p>從Ubuntu桌面版CD/DVD或者USB啓動後，在歡迎頁面點擊“Try Ubuntu”。</p><p><img src="https://c1.staticflickr.com/1/586/22195371892_3816ba09c3_c.jpg" alt=""></p><p>當你進入live Ubuntu後，點擊左邊的設置圖標。</p><p><img src="https://c1.staticflickr.com/1/723/22020327738_058610c19d_c.jpg" alt=""></p><p>進入網絡菜單。</p><p><img src="https://c2.staticflickr.com/6/5675/22021212239_ba3901c8bf_c.jpg" alt=""></p><p>手動配置代理。</p><p><img src="https://c1.staticflickr.com/1/735/22020025040_59415e0b9a_c.jpg" alt=""></p><p>接下來，打開終端。</p><p><img src="https://c2.staticflickr.com/6/5642/21587084823_357b5c48cb_c.jpg" alt=""></p><p>輸入下面的命令進入root會話。</p><pre><code>$ sudo su
</code></pre><p>最後以root權限輸入下面的命令。</p><pre><code># ubiquity gtk_ui
</code></pre><p>它會啓動基於GUI的Ubuntu安裝器。</p><p><img src="https://c1.staticflickr.com/1/723/22020025090_cc64848b6c_c.jpg" alt=""></p><p>接着完成剩餘的安裝。</p><p><img src="https://c1.staticflickr.com/1/628/21585344214_447020e9d6_c.jpg" alt=""></p><hr>`,26)),o("p",null,[t[1]||(t[1]=n("via: ",-1)),p(u,{href:"http://ask.xmodulo.com/install-ubuntu-desktop-behind-proxy.html"},{default:s(()=>[...t[0]||(t[0]=[n("http://ask.xmodulo.com/install-ubuntu-desktop-behind-proxy.html",-1)])]),_:1})]),o("p",null,[t[5]||(t[5]=n("作者：",-1)),p(u,{href:"http://ask.xmodulo.com/author/nanni"},{default:s(()=>[...t[2]||(t[2]=[n("Dan Nanni",-1)])]),_:1}),t[6]||(t[6]=n(" 譯者：",-1)),p(u,{href:"https://github.com/geekpi"},{default:s(()=>[...t[3]||(t[3]=[n("geekpi",-1)])]),_:1}),t[7]||(t[7]=n(" 校對：",-1)),p(u,{href:"https://github.com/wxy"},{default:s(()=>[...t[4]||(t[4]=[n("wxy",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=n("本文由 ",-1)),p(u,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[8]||(t[8]=[n("LCTT",-1)])]),_:1}),t[11]||(t[11]=n(" 原創編譯，",-1)),p(u,{href:"https://linux.cn/"},{default:s(()=>[...t[9]||(t[9]=[n("Linux中國",-1)])]),_:1}),t[12]||(t[12]=n(" 榮譽推出",-1))])])}const T=i(b,[["render",d]]);export{k as __pageData,T as default};
